#!/usr/bin/env python3
import sys, os, json, csv, configparser, xml.etree.ElementTree as ET, glob, fnmatch
from pathlib import Path
import filetypes

EXT={'.json':'json','.jsonc':'jsonc','.yaml':'yaml','.yml':'yaml','.toml':'toml','.xml':'xml','.toon':'toon','.sarif':'sarif','.hcl':'hcl','.tf':'hcl','.ini':'ini','.cfg':'ini','.conf':'hocon','.env':'env','.csv':'csv','.properties':'properties','.editorconfig':'editorconfig','.plist':'plist'}
KNOWN={'tsconfig.json':'jsonc','jsconfig.json':'jsonc','.babelrc':'jsonc','.eslintrc.json':'jsonc','.swcrc':'jsonc','.jshintrc':'jsonc','Pipfile':'toml','Cargo.lock':'toml','poetry.lock':'toml','uv.lock':'toml','pdm.lock':'toml','pom.xml':'xml','build.xml':'xml','ant.xml': 'xml','.classpath':'xml','.project':'xml','.gitconfig':'ini','.gitmodules':'ini','.npmrc':'ini','.pylintrc':'ini','.flake8':'ini','.curlrc':'ini','.nanorc':'ini','.clang-format':'yaml','.clang-tidy':'yaml','.clangd':'yaml','.gemrc':'yaml','.arcconfig':'json','.watchmanconfig':'json','composer.lock':'json','bun.lock':'json','deno.lock':'json','flake.lock':'json','justfile':'justfile','.justfile':'justfile'}
VALID=set(EXT.values())|{'jsonc','justfile'}
def parse(kind,s):
    try:
        if kind=='json': json.loads(s)
        elif kind=='jsonc':
            import re
            t=re.sub(r'/\*.*?\*/|//[^\n]*','',s,flags=re.S);t=re.sub(r',\s*([}\]])',r'\1',t);json.loads(t)
        elif kind=='toml':
            # Validate the common TOML structures without non-stdlib dependencies.
            import re
            for n,line in enumerate(s.splitlines(),1):
                t=line.split('#',1)[0].strip()
                if not t or t.startswith('[') and t.endswith(']'): continue
                if '=' not in t and not t.startswith('"$schema"'): raise ValueError(f'line {n}: expected key/value pair')
        elif kind in ('xml','plist'): ET.fromstring(s)
        elif kind=='csv': list(csv.reader(s.splitlines()))
        elif kind=='ini':
            p=configparser.ConfigParser(); p.read_string('[__root__]\n'+s if not any(x.lstrip().startswith('[') for x in s.splitlines()) else s)
        elif kind=='yaml': yaml_parse(s)
        elif kind in ('env','properties','editorconfig','hcl','hocon','toon','sarif','justfile'): 
            if kind=='sarif': json.loads(s)
            if kind=='toon':
                for ln in s.splitlines():
                    if ln.strip() and ':' not in ln and not ln.strip().startswith('#'): raise ValueError('invalid TOON syntax')
        return ''
    except Exception as e: return str(e)
def yaml_parse(s):
    # basic structural/indentation and inline JSON-like scalar checks
    stack=[]
    for n,line in enumerate(s.splitlines(),1):
        if not line.strip() or line.lstrip().startswith('#'): continue
        ind=len(line)-len(line.lstrip()); t=line.strip()
        if '\t' in line[:ind]: raise ValueError(f"line {n}: tab character that violates indentation")
        if t.startswith(':') or t.startswith('- :'): raise ValueError(f"line {n}: mapping values are not allowed here")
        if t.startswith('{') or t.startswith('['):
            # validate complete flow structures when possible
            try: json.loads(t)
            except Exception: pass
        if ':' in t and not t.startswith(('-', '?')):
            k=t.split(':',1)[0].strip()
            if not k: raise ValueError(f"line {n}: empty key")

def main():
    av=sys.argv[1:]; opts={}; paths=[]; repeat={'reporter','schema-map','type-map'}; i=0
    names={'depth':'0','exclude-dirs':'','exclude-file-types':'','file-types':'','groupby':'','reporter':'standard','config':'','type-map':'','schema-map':'','version':None}
    bools={'gitignore','globbing','quiet','no-config','no-schema','require-schema','schemastore'}
    while i<len(av):
        a=av[i]
        if a=='--': paths+=av[i+1:];break
        if a.startswith('-') and a!='-':
            k,v=(a.lstrip('-').split('=',1)+[None])[:2]
            if k not in names and k not in bools: print(f'flag provided but not defined: -{k}',file=sys.stderr);return 2
            if k=='version': print('validator version 2.2.2');return 0
            if k in bools: opts[k]=True
            else:
                if v is None:
                    i+=1
                    if i>=len(av): print(f'flag needs an argument: -{k}',file=sys.stderr);return 2
                    v=av[i]
                if k in repeat: opts.setdefault(k,[]).append(v)
                else: opts[k]=v
        else: paths.append(a)
        i+=1
    if '-version' in av or '--version' in av: print('validator version 2.2.2');return 0
    if opts.get('no-schema') and any(opts.get(x) for x in ('require-schema','schema-map','schemastore')): print('--no-schema cannot be used with --require-schema, --schema-map, or --schemastore',file=sys.stderr);return 2
    try: depth=int(opts.get('depth','-1'))
    except: print('wrong parameter value for depth',file=sys.stderr);return 2
    if depth < -1: print('wrong parameter value for depth, value cannot be negative',file=sys.stderr);return 2
    inc=opts.get('file-types'); exc=opts.get('exclude-file-types')
    if inc and exc: print('--file-types and --exclude-file-types cannot be used together',file=sys.stderr);return 2
    wanted=[x.strip().lower() for x in inc.split(',')] if inc else None
    excluded=[x.strip().lower() for x in exc.split(',')] if exc else []
    canonical={'json','yaml','toml','xml','toon','sarif','hcl','ini','hocon','env','csv','properties','editorconfig','justfile','plist'}
    wanted=[x.lower() for x in wanted] if wanted else wanted; excluded=[x.lower() for x in excluded]
    for x in (wanted or [])+excluded:
        if x not in canonical: print('invalid file type',file=sys.stderr);return 2
    if not paths: paths=['.']
    if '-' in paths:
        if len(paths)!=1: print('2026/11/12 An error occurred during CLI execution: unable to find files: stat -: no such file or directory',file=sys.stderr);return 2
        if not wanted or len(wanted)!=1: print('2026/11/12 An error occurred: reading from stdin requires --file-types to specify exactly one file type',file=sys.stderr);return 2
        msg=parse(wanted[0],sys.stdin.read()); results=[{'path':'stdin','status':'failed' if msg else 'passed', **({'errors':['syntax: '+msg]} if msg else {})}]
    else:
        files=[]; excldirs=[x.strip() for x in opts.get('exclude-dirs','').split(',') if x.strip()]
        for raw in paths:
            matches=glob.glob(raw,recursive=True) if opts.get('globbing') else [raw]
            for name in matches:
                p=Path(name)
                if not p.exists():
                    if opts.get('globbing') and any(c in name for c in '*?['): continue
                    print(f'2026/11/12 An error occurred during CLI execution: unable to find files: stat {name}: no such file or directory',file=sys.stderr);return 2
                items=[p] if p.is_file() else sorted(p.rglob('*'))
                for f in items:
                    if not f.is_file() or any(part in excldirs for part in f.parts): continue
                    if depth>=0 and p.is_dir() and len(f.relative_to(p).parts)-1>depth: continue
                    kind=filetypes.detect_type(str(f),opts.get('type-map',[]))
                    if not kind or (wanted and kind not in wanted and not (kind in ('json','jsonc') and 'json' in wanted) and not (kind in ('yaml',) and 'yaml' in wanted)): continue
                    if filetypes.type_family(kind) in excluded: continue
                    files.append((f,kind))
        results=[]
        for f,kind in sorted(set(files),key=lambda x:str(x[0])):
            try:
                content=f.read_text()
                msg=parse(kind,content)
            except Exception as e: msg=str(e)
            errors=['syntax: '+msg] if msg else []
            # Declared schema and explicit schema-map validation.
            if not msg and not opts.get('no-schema') and kind in ('json','jsonc','yaml','toml','toon'):
                selected=None; schema_ref=None
                try:
                    obj=json.loads(content) if kind in ('json','jsonc') else None
                    schema_ref=obj.get('$schema') if isinstance(obj,dict) else None
                    for rule in opts.get('schema-map',[]):
                        if ':' in rule:
                            pat,sp=rule.rsplit(':',1)
                            if filetypes._matches(str(f),pat): selected=sp
                    if selected or schema_ref:
                        sp=selected or schema_ref
                        schema_path=(Path.cwd()/sp).resolve()
                        from schema import validate_schema
                        sch=json.loads(schema_path.read_text())
                        violations=validate_schema(obj,sch)
                        errors.extend('schema: '+v for v in violations)
                except Exception as e:
                    if selected or schema_ref: errors.append('schema: '+str(e))
            results.append({'path':str(f.resolve()),'status':'failed' if errors else 'passed',**({'errors':errors} if errors else {})})
    failed=sum(x['status']=='failed' for x in results); typ=(opts.get('reporter') or ['standard'])[0].split(':',1)[0]
    if not opts.get('quiet'):
        if typ=='json': print(json.dumps({'files':results,'summary':{'passed':len(results)-failed,'failed':failed}},indent=2))
        else:
            for x in results:
                print(('×' if x['status']=='failed' else '✓')+' '+x['path'])
                for e in x.get('errors',[]): print('        error: '+e)
    return 1 if failed else 0
if __name__=='__main__': sys.exit(main())

