"""Grouping helpers for the standard and JSON reports."""
import os
from collections import OrderedDict

VALID_GROUPS = {'filetype', 'directory', 'pass-fail', 'error-type'}


def normalize_groups(value):
    if not value:
        return []
    groups = [x.strip().lower() for x in value.split(',') if x.strip()]
    bad = [x for x in groups if x not in VALID_GROUPS]
    if bad:
        raise ValueError('wrong parameter value for groupby, only supports filetype, directory, pass-fail, error-type')
    return groups


def label_for(result, group, kinds):
    path = result['path']
    if group == 'filetype':
        return kinds.get(path, 'unknown')
    if group == 'directory':
        return os.path.dirname(path) or '.'
    if group == 'pass-fail':
        return 'Passed' if result['status'] == 'passed' else 'Failed'
    if result['status'] == 'passed':
        return 'Passed'
    errors = result.get('errors') or ['error']
    return errors[0].split(':', 1)[0]


def _insert(tree, labels, result):
    node = tree
    for label in labels:
        node = node.setdefault(label, OrderedDict())
    node.setdefault('_items', []).append(result)


def _walk_counts(items):
    passed = failed = 0
    for key, val in items.items():
        if key == '_items':
            passed += sum(x['status'] == 'passed' for x in val)
            failed += sum(x['status'] == 'failed' for x in val)
        else:
            p, f = _walk_counts(val)
            passed += p; failed += f
    return passed, failed


def json_grouped(results, groups, kinds):
    files = OrderedDict()
    for result in results:
        _insert(files, [label_for(result, g, kinds) for g in groups], result)

    def summary_tree(node):
        out = OrderedDict()
        for key, child in node.items():
            if key == '_items':
                p = sum(x['status'] == 'passed' for x in child)
                f = sum(x['status'] == 'failed' for x in child)
                out.setdefault('_summary', []).append({'passed': p, 'failed': f})
            else:
                sub = summary_tree(child)
                out[key] = sub.get('_summary', sub)
        return out

    def file_tree(node):
        out = OrderedDict()
        for key, child in node.items():
            if key == '_items':
                return child
            out[key] = file_tree(child)
        return out

    def sorted_tree(value):
        if isinstance(value, dict):
            return OrderedDict((k, sorted_tree(v)) for k, v in sorted(value.items(), key=lambda x: str(x[0])))
        return value

    return {'files': sorted_tree(file_tree(files)), 'summary': sorted_tree(summary_tree(files)),
            'totalPassed': sum(x['status'] == 'passed' for x in results),
            'totalFailed': sum(x['status'] == 'failed' for x in results)}


def standard_grouped(results, groups, kinds):
    tree = OrderedDict()
    for result in results:
        _insert(tree, [label_for(result, g, kinds) for g in groups], result)
    lines = []

    def render(node, level):
        first = True
        for key, val in sorted(node.items(), key=lambda x: str(x[0])):
            if not first:
                lines.append('')
            first = False
            if key == '_items':
                for result in val:
                    ok = result['status'] == 'passed'
                    lines.append('    ' * level + ('✓ ' if ok else '× ') + result['path'])
                    lines.extend('    ' * (level + 1) + 'error: ' + e for e in result.get('errors', []))
            else:
                lines.append('    ' * level + str(key))
                render(val, level + 1)
                p, f = _walk_counts({key: val})
                if len(groups) == 1 and groups[0] in ('filetype', 'directory', 'error-type'):
                    lines.append('')
                    lines.append('    ' * level + f'Summary: {p} succeeded, {f} failed')
    render(tree, 0)
    p = sum(x['status'] == 'passed' for x in results)
    f = sum(x['status'] == 'failed' for x in results)
    lines.append('')
    lines.append(f'Total Summary: {p} succeeded, {f} failed')
    return '\n'.join(lines) + ('\n' if lines else '')
