"""SARIF and GitHub Actions reporters matching validator output."""
import json
import re
from urllib.parse import quote

_LOCATION = re.compile(r'\bline\s+(\d+)(?:,\s*column\s+(\d+))?', re.I)


def _location_error(message):
    match = _LOCATION.search(message)
    if not match:
        return None, None
    return int(match.group(1)), int(match.group(2)) if match.group(2) else None


def _uri(path):
    # The Go implementation emits file://// for absolute Unix paths.
    if path.startswith('/'):
        return 'file:///' + quote(path, safe='/')
    return quote(path, safe='/')


def sarif(results):
    output=[]
    for item in results:
        loc={'physicalLocation': {'artifactLocation': {'uri': _uri(item['path'])}}}
        errors=item.get('errors') or []
        if not errors:
            output.append({'kind':'pass','level':'none','message':{'text':'No errors detected'},'locations':[loc]})
            continue
        for error in errors:
            line,col=_location_error(error)
            if line is not None:
                region={'startLine':line}
                if col is not None: region['startColumn']=col
                loc={'physicalLocation': {'artifactLocation': {'uri':_uri(item['path'])}, 'region':region}}
            output.append({'kind':'fail','level':'error','message':{'text':error},'locations':[loc]})
