"""Lightweight checks for the versioned SARIF format."""
import json
import re

_LANGUAGE = re.compile(r'^[a-zA-Z]{2}(-[a-zA-Z]{2})?$')


def decode(text):
    """Decode SARIF and reject version/schema markers that cannot be selected."""
    data = json.loads(text)
    if not isinstance(data, dict):
        raise ValueError('unable to determine sarif version')
    marker = data.get('$schema', '')
    version = data.get('version', '')
    schema_version = None
    for candidate in ('2.1.0',):
        if candidate in marker:
            schema_version = candidate
            break
    if not schema_version or version != schema_version:
        raise ValueError('unable to determine sarif version')
    runs = data.get('runs')
    if runs is not None and not isinstance(runs, list):
        raise ValueError('json: cannot unmarshal object into Go struct field Report.runs of type []*sarif.Run')
    return data


def schema_errors(data):
    errors=[]
    runs=data.get('runs', [])
    for i,run in enumerate(runs):
        if not isinstance(run, dict):
            continue
        prefix=f'runs.{i}'
        if 'tool' not in run:
            errors.append(f'{prefix}: tool is required')
        tool=run.get('tool')
        newlines=run.get('newlineSequences', [])
        if not isinstance(newlines, list) or len(newlines)<1:
            errors.append(f'{prefix}.newlineSequences: Array must have at least 1 items')
        if isinstance(tool, dict):
            driver=tool.get('driver')
            if isinstance(driver,dict):
                dlang=driver.get('language','')
                if not isinstance(dlang,str) or not _LANGUAGE.fullmatch(dlang):
                    errors.append(f"{prefix}.tool.driver.language: Does not match pattern '^[a-zA-Z]{{2}}(-[a-zA-Z]{{2}})?$'")
        lang=run.get('language', '')
        if not isinstance(lang, str) or not _LANGUAGE.fullmatch(lang):
            errors.append(f"{prefix}.language: Does not match pattern '^[a-zA-Z]{{2}}(-[a-zA-Z]{{2}})?$'")
    return errors
