def glob_expand(pattern):
    import re
    match=re.search(r'\{([^{}]+)\}',pattern)
    if not match: return glob.glob(pattern,recursive=True)
    values=match.group(1).split(',')
    expanded=[]
    for value in values:
        expanded.extend(glob_expand(pattern[:match.start()]+value+pattern[match.end():]))
    return sorted(set(expanded))

